/* Database : shop */
SET NAMES utf8mb4;

CREATE TABLE `src` (
  `a` int NOT NULL,
  PRIMARY KEY (`a`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v` AS select `v`() AS `n`,`src`.`a` AS `a` from `src`;

/* Routines */
SET @OLD_ROUTINE_SQL_MODE = @@SQL_MODE, SQL_MODE = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` FUNCTION `v`() RETURNS int
    NO SQL
    DETERMINISTIC
RETURN 1;;
DELIMITER ;
SET SQL_MODE = @OLD_ROUTINE_SQL_MODE;
